when.condition:
@{
                var form = context.Request.Body.AsFormUrlEncodedContent(true);
                if (form == null) { return true; }
                var id = form.ContainsKey("client_id") ? form["client_id"][0].Trim() : "";
                var secret = form.ContainsKey("client_secret") ? form["client_secret"][0].Trim() : "";
                var scope = form.ContainsKey("scope") ? form["scope"][0].Trim() : "";
                return id.Length == 0 || secret.Length == 0 || (scope.Length != 0 ? !scope.EndsWith("/.default") : false);
            }

inbound.set-body:
@{
            var form = context.Request.Body.AsFormUrlEncodedContent(true);
            var scope = form.ContainsKey("scope") ? form["scope"][0].Trim() : "";
            if (scope.Length == 0) { scope = "${default_scope}"; }
            return "grant_type=client_credentials"
                + "&client_id=" + Uri.EscapeDataString(form["client_id"][0].Trim())
                + "&client_secret=" + Uri.EscapeDataString(form["client_secret"][0].Trim())
                + "&scope=" + Uri.EscapeDataString(scope);
        }
